@F.udf(TimestampType())
def parse_twitter_timestamp(value):
    if value is None:
        return None

    try:
        return datetime.strptime(
            value,
            "%a %b %d %H:%M:%S %z %Y"
        ).replace(tzinfo=None)
    except Exception:
        return None


tweets_session = (
    tweets

    .withColumn(
        "tweet_timestamp_utc",
        parse_twitter_timestamp(
            F.col("tweet_created_at")
        )
    )

    .withColumn(
        "tweet_timestamp_et",
        F.from_utc_timestamp(
            F.col("tweet_timestamp_utc"),
            "America/New_York"
        )
    )

    .withColumn(
        "tweet_date_et",
        F.to_date("tweet_timestamp_et")
    )
)


tweets_session.agg(
